import React from 'react';
import Header from '@/components/Header';
import Hero from './components/Hero';
import Services from './components/Services';

function App() {
  return (
    <div className='App'>
      <Header />
      <main>
        <h1 className='visually-hidden'>Get your own bank card</h1>
        <Hero />
        <Services />
      </main>
    </div>
  );
}

export default App;
